    const dx = b[0] - a[0], dz = b[1] - a[1];
    const denominator = dx * dx + dz * dz;
    const t = denominator > 0 ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / denominator)) : 0;
    return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dz);
  }
  const routeSegments = paths.slice();
  for (let side = 0; side < 2; side++) {
    for (let i = 0; i < lanes[side].length - 1; i++) routeSegments.push([lanes[side][i], lanes[side][i + 1]]);
    routeSegments.push([lanes[side][crossing.index], side === 0 ? crossing.left : crossing.right]);
  }
  function clear(p) {
    if (Math.abs(p[0] - riverX(p[1])) < 6) return false;
    for (let i = 0; i < occupied.length; i++) {
      if (distance(p, occupied[i].p) < occupied[i].radius + 2.5) return false;
    }
    for (let i = 0; i < routeSegments.length; i++) {
      if (segmentDistance(p, routeSegments[i][0], routeSegments[i][1]) < 4) return false;
    }
    return true;
  }
